/**
 * Read-only visibility pass over the macOS system-level projections setup writes.
 *
 * Every other global check walks the canonical -> runtime-home file projection
 * chain. Setup also writes outside that chain — a LaunchAgent plist and the MCP
 * Memory start script — and `install-manifest.json` does not record either, so
 * nothing in the repository can currently tell you they exist, let alone which
 * version produced them. A script generated by an old release survives
 * indefinitely while every check reports green.
 *
 * This module makes those files visible. It deliberately does NOT decide
 * whether they are correct:
 *
 * - It never invokes `launchctl`, matching the installer's stance of projecting
 *   files rather than driving service lifecycle.
 * - It never fails the global check. Ownership cannot be established from a
 *   filename, and prior releases legitimately produced scripts that today's
 *   generator would not, so a hard gate would fail existing installs that have
 *   no repair command to run. Findings are reported for a human to judge.
 *
 * Recording these projections in the install manifest is the real fix; once
 * entries carry a recorded hash, this pass can compare against it instead of
 * inspecting file bodies. Until then it reports observations, not verdicts.
 */

import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";
import process from "node:process";

/**
 * Boot labels the current generator still produces (setup.mjs writes the plist
 * and Label at 7153/7157 and removes it at 7320). A `com.meta-kim.*` file
 * outside this list was written by an older release, by a different tool, or by
 * the user — this module cannot tell which, so it reports rather than judges.
 */
export const CURRENT_MACOS_BOOT_LABELS = Object.freeze([
  "com.meta-kim.mcp-memory-service",
]);

/**
 * @returns {Promise<{findings: Array<{severity: "info"|"notice", kind: string, message: string}>}>}
 */
export async function auditMacosSystemLevelProjections({
  homeRoot = os.homedir(),
  platform = process.platform,
} = {}) {
  const findings = [];
  if (platform !== "darwin") return { findings };

  const launchAgentsDir = path.join(homeRoot, "Library", "LaunchAgents");
  let entries = null;
  try {
    entries = await fs.readdir(launchAgentsDir);
  } catch (error) {
    // A missing directory means nothing was ever projected. Anything else
    // (permissions, I/O) means the audit could not see, which is not the same
    // as "clean" and must not be swallowed.
    if (error.code !== "ENOENT") {
      findings.push({
        severity: "notice",
        kind: "launch-agents-unreadable",
        message: `Could not read ${launchAgentsDir} (${error.code}); macOS LaunchAgent state is unknown`,
      });
    }
  }

  for (const name of (entries ?? []).filter((entry) => entry.startsWith("com.meta-kim.")).sort()) {
    const filePath = path.join(launchAgentsDir, name);
    // launchd only loads a `.plist`; any other suffix (`.disabled`, `.bak`) is
    // inert. This says nothing about intent — it is just not loadable.
    if (!name.endsWith(".plist")) {
      findings.push({
        severity: "info",
        kind: "launch-agent-inert",
        message: `macOS LaunchAgent file not loadable by launchd (inert): ${filePath}`,
      });
      continue;
    }
    const label = name.slice(0, -".plist".length);
    if (!CURRENT_MACOS_BOOT_LABELS.includes(label)) {
      findings.push({
        severity: "notice",
        kind: "launch-agent-unrecognized",
        message: `macOS LaunchAgent no current code path generates: ${filePath} (review before removing; it may predate this release or belong to another tool)`,
      });
      continue;
    }
    findings.push({
      severity: "info",
      kind: "launch-agent",
      message: `macOS LaunchAgent ${label}: ${filePath}`,
    });
  }

  const startScript = path.join(homeRoot, ".meta-kim", "mcp-memory-start.sh");
  let startScriptBody = null;
  try {
    startScriptBody = await fs.readFile(startScript, "utf8");
  } catch (error) {
    if (error.code !== "ENOENT") {
      findings.push({
        severity: "notice",
        kind: "start-script-unreadable",
        message: `Could not read ${startScript} (${error.code}); generated start script state is unknown`,
      });
    }
  }
  if (startScriptBody !== null) {
    // Heuristic, not proof of provenance: today's generator reports failures by
    // appending to the log file and emits no GUI dialog, so a script that
    // raises one was produced by an older release. A path or comment containing
    // this substring would also match, hence "review", not "fail".
    const raisesGuiDialog = /osascript/iu.test(startScriptBody);
    findings.push(
      raisesGuiDialog
        ? {
            severity: "notice",
            kind: "start-script-raises-dialog",
            message: `Generated MCP Memory start script raises a GUI dialog; the current generator logs instead, so this likely predates this release: ${startScript}`,
          }
        : {
            severity: "info",
            kind: "start-script",
            message: `Generated MCP Memory start script: ${startScript}`,
          },
    );
  }

  return { findings };
}
